import{_ as C,a0 as d,w as p,s as n,ao as l,I as s,x as t,a1 as r,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"為什麼 Fedora 一開始允許使用 CC0 許可證 | LCTT x X-CMD","titleTemplate":false,"description":"為什麼 Fedora 一開始允許使用 CC0 許可證 | LCTT (202208) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"為什麼 Fedora 一開始允許使用 CC0 許可證 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"為什麼 Fedora 一開始允許使用 CC0 許可證 | LCTT (202208) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202208/20220801 What Made Fedora Choose To Use CC0 Licensed Code As The Boot","title":"為什麼 Fedora 一開始允許使用 CC0 許可證","tag":"202208","desc":""},"relativePath":"202208/20220801 What Made Fedora Choose To Use CC0 Licensed Code As The Boot.md","filePath":"[post].md"}'),i={name:"202208/20220801 What Made Fedora Choose To Use CC0 Licensed Code As The Boot.md"};function u(m,e,f,T,h,F){const o=d("Link");return p(),n("div",null,[e[15]||(e[15]=l('<h1 id="為什麼-fedora-一開始允許使用-cc0-許可證" tabindex="-1">為什麼 Fedora 一開始允許使用 CC0 許可證 <a class="header-anchor" href="#為什麼-fedora-一開始允許使用-cc0-許可證" aria-label="Permalink to “為什麼 Fedora 一開始允許使用 CC0 許可證”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202208/12/160739j1eqft2cpw7srssz.png" alt=""></p><p>開源是一個具有挑戰性的概念。許多人認為，開源意味着可以任意的使用軟件，並且可以免費下載。這實際上取決於你如何被許可 —— 開發者分享代碼時使用的許可證決定了它。開源軟件可以是收費的，也可以限制你如何去使用它，在極少數情況下，甚至讓你陷入法律糾紛。</p><p>Fedora 項目最近決定拒絕所有使用 <ruby>知識共享<rt>Creative Commons</rt></ruby> “公共領域專用” CC0 許可證的代碼，以避免這種情況的出現。CC0 將從新提交代碼中准許使用的許可證列表中剔除，但是，像藝術品一類的貢獻仍被允許所以它，甚至可能在個案的情況下對當前的軟件包進行逐一的處理。</p><p>如果 Fedora 反對一個軟件許可證，通常不會成為新聞。事實上，在那麼多的許可證當中，該項目拒絕了許多許可證。這種情況的意外之處在於，CC0 最初被認為是一個有效的許可證，現在只是由於更大的自由及開源（FOSS）社區內的觀點轉變而被重新分類。</p><p>CC0 是因為什麼讓 Fedora 決定停止支持它，這又是否意味着你不能在你自己的項目中使用它呢？</p><p>這一段描述讓最熟悉知識共享及其許可系列的人驚訝的是，Fedora 最初批准了 CC0 的軟件。畢竟，知識共享從一開始的目標是為藝術作品提供一系列明確的許可證。該組織的使命和許可證的要求在其名稱“知識共享”中就有所體現。</p><p>為了“克服分享信息和創造力的法律障礙”，提供一個自由的框架來為人們組織分享如音樂、醫學或教育材料的資源，知識共享組織的前身——<ruby>開放內容項目<rt>Open Content Project</rt></ruby>，於 2001 年成立。然而，軟件從來不是它的組成要素。為什麼呢？因為那時，如 MIT、GPL 一類的重要的軟件許可證已經出現了十幾年。</p><p>很明顯，如果一家公司不遺餘力地警告你他們製造的東西不適合某種特定用途，你也許應該相信他們。知識共享的 FAQ 列出了一些反對在軟件上使用他們的許可證的令人信服的論據，但對於像 Fedora 項目這樣的用户來説，其中一個問題特別突出：專利權。</p><p>鑑於 CC0 許可證是為公共領域的作品準備的，而且通過使用它，創作者明確地“放棄了他或她在版權法下對作品的所有權利”，這似乎矛盾的。但是，問題在於，版權法並不適用於專利。事實上，仔細審視許可證的完整措辭後可以發現，它在一個令人擔憂的部分解決了這個問題，該部分內容如下：“宣告者擁有的任何商標或專利權都沒有被本文本放棄、拋棄、交出、租賃或以其他方式修改。”</p><p>換言之，即使被 CC0 許可的東西的作者可能願意放棄對它的權力，但他們仍然可以自由的為它申請專利。更糟糕的是，他們仍然保留着以他們認為合適的方式使用該專利的能力。</p><p>理論上來説，這意味着最初在 CC0 下提供的源代碼的人在發佈了代碼之後，他們可能會在之後斷言任何使用該代碼的人侵犯了他們的專利，並要求支付專利費。</p><p>這顯然會讓像 Fedora 這樣的項目擔憂。考慮一下這樣的情形：CC0 許可的代碼進入到一個系統的核心，然後被提供給數以百萬計的用户。突然間，不知道從哪裏冒出來的原創作者，聲稱侵犯了專利權，並要求付款。紅帽或 Fedora 的律師可以駁倒這種説法麼？也許吧。那麼，為了查明真相而使用 CC0 代碼值得麼？不值得。</p><p>要着重提到的是，這完全不是一個新問題。實際上，早在 2012 年，專利條款就阻止了開源倡議（OSI）許可證的審查委員會，他們無法最終確定 CC0 是否真正符合他們對開源許可證的定義。委員會未能達成一致意見，因為其成員認為將此類條款納入軟件許可將創造一個危險的先例。考慮到 Fedora 動盪的歷史，它最初接受 CC0 的決定着實讓人費解。</p><hr>',15)),s("p",null,[e[1]||(e[1]=t("via: ",-1)),r(o,{href:"https://www.opensourceforu.com/2022/08/what-made-fedora-choose-to-use-cc0-licensed-code-as-the-boot/"},{default:a(()=>[...e[0]||(e[0]=[t("https://www.opensourceforu.com/2022/08/what-made-fedora-choose-to-use-cc0-licensed-code-as-the-boot/",-1)])]),_:1})]),s("p",null,[e[6]||(e[6]=t("作者：",-1)),r(o,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:a(()=>[...e[2]||(e[2]=[t("Laveesh Kocher",-1)])]),_:1}),e[7]||(e[7]=t(" 選題：",-1)),r(o,{href:"https://github.com/lkxed"},{default:a(()=>[...e[3]||(e[3]=[t("lkxed",-1)])]),_:1}),e[8]||(e[8]=t(" 譯者：",-1)),r(o,{href:"https://github.com/yjacks"},{default:a(()=>[...e[4]||(e[4]=[t("yjacks",-1)])]),_:1}),e[9]||(e[9]=t(" 校對：",-1)),r(o,{href:"https://github.com/wxy"},{default:a(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[12]||(e[12]=t("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原創編譯，",-1)),r(o,{href:"https://linux.cn/"},{default:a(()=>[...e[11]||(e[11]=[t("Linux中國",-1)])]),_:1}),e[14]||(e[14]=t(" 榮譽推出",-1))])])}const b=C(i,[["render",u]]);export{L as __pageData,b as default};
